window.KT_JURORS = [{"id": "dr-archana-yemeshvary-upadhyay", "name": "Dr. Archana Yemeshvary Ashok Upadhyay (PhD)", "title": "CHRO, Hindustan Colas Pvt. Ltd", "img": "img/jurors/dr-archana-yemeshvary-upadhyay.jpg", "bio": "Dr. Archana is an accomplished CXO Coach and a seasoned HR leader with over three decades of invaluable experience. In her current pivotal role as the Chief Human Resources Officer at Hindustan Colas, she is a driving force behind organizational transformation, renowned for her exceptional ability to foster high-performance cultures, shape impactful leaders, and empower individuals to truly achieve their full potential.", "links": [{"l": "LinkedIn", "h": "https://www.linkedin.com/in/dr-archana-yemeshvary-ashok-upadhyay"}]}, {"id": "moera-saule", "name": "Moëra Saule", "title": "Leadership & Inner Coherence Coach and Mentor at ShapeYourOwnWorld", "img": "img/jurors/moera-saule.jpg", "bio": "Leadership & Inner Coherence Coach and Mentor, I operate at the level where seasoned coaches and people of influence consolidate robust, coherent and sustainable businesses and signatures, while elevating decision-making, presence and impact. My work sits at the intersection of conscious performance, strategic clarity and inner coherence. I intervene where conventional models reach their limits when success is already established and the next level demands greater discernment, mastery and embodied leadership.", "links": [{"l": "Facebook", "h": "https://www.facebook.com/moerasaule.shapeyourownworld"}, {"l": "Instagram", "h": "https://www.instagram.com/moera_saule/"}, {"l": "LinkedIn", "h": "https://bit.ly/4sua59L"}]}, {"id": "arnor-mar-masson", "name": "Arnór Már Másson", "title": "Executive & Business Coach · Mentor · Books Writer", "img": "img/jurors/arnor-mar-masson.jpg", "bio": "Arnór Már is one of the most experienced coaches in Iceland. He is: Master Certified Coach, International Coaching Federation BSc in Psychology from the University of Iceland PDE in Entrepreneurship from Keilir, the University of Iceland and the Icelandic Innovation Center. Arnór Már has good intuition and has understanding and sensitivity in communication. He helps you deepen your communication and the ability to be close in relationships. You learn to read what brings you happiness and gives your life purpose. Arnór is also practical. He gives you tools and equipment to move forward in life.", "links": [{"l": "LinkedIn", "h": "https://bit.ly/4oohW6m"}]}, {"id": "jory-stillman", "name": "Jory Stillman", "title": "Founder of ExpansiveCoach™ · ICF Mentor, Trainer & Assessor · Facilitator", "img": "img/jurors/jory-stillman.jpg", "bio": "Welcome, I’m Jory founder of ExpansiveCoach. My mission is to guide people toward lives and careers rooted in clarity, purpose, well-being, and impact. I partner with thoughtful, growth-oriented individuals navigating the complexities of real life: leading in demanding careers while nurturing marriages or relationships, raising children or supporting adult children in transition, fulfilling meaningful community responsibilities, and caring for aging parents. These are people who carry a lot and who want to move through it with steadiness, authenticity, and intention.", "links": [{"l": "LinkedIn", "h": "https://www.linkedin.com/in/jorystillman/"}, {"l": "Website", "h": "https://www.jorystillmancoaching.com"}]}, {"id": "lerae-gidyk", "name": "Lerae Gidyk", "title": "Founder of Soul Designs Coaching Int'l Ltd · Coach Mentor and Leadership Coach", "img": "img/jurors/lerae-gidyk.jpg", "bio": "Lerae Gidyk is an ICF Master Certified Coach (MCC), pioneer, and thought leader in the global coaching profession. Since 1999, she has been coaching in personal, leadership, and mentor coaching, bringing a profound commitment to the embodiment of humanness in coaching coaching not only as a skillset, but as a way of being.", "links": [{"l": "Facebook", "h": "https://www.facebook.com/souldesignscoaching/"}, {"l": "Instagram", "h": "https://www.instagram.com/souldesignscoaching/"}, {"l": "LinkedIn", "h": "https://www.linkedin.com/in/leraegidyk"}]}, {"id": "priya-ramesh", "name": "Priya Ramesh", "title": "Co-Founder, ORENDA Centre for Leadership Excellence", "img": "img/jurors/priya-ramesh.jpg", "bio": "Coach practitioner, Coach Supervisor, Coach Educator, Co Founder, ORENDA Centre for Leadership Excellence working in the space of Leadership Development enabling high impact performance Professional integrity, authenticity, trust, commitment, humility are hallmarks of my leadership style. I lead by example and firm believer that power is inherent in all. I embody this philosophy in how I engage with the coaching community, coaching clients and with leaders in Organisation.", "links": [{"l": "LinkedIn", "h": "https://www.linkedin.com/in/priya-ramesh-leadership-coach-b015119/"}]}, {"id": "alex-tan", "name": "Alex Tan", "title": "Managing Director at Avidity International · Master Coach-Facilitator", "img": "img/jurors/alex-tan.jpg", "bio": "Alex is a Master Certified Coach (MCC) with ICF, a Certified Master Solution-Focused Coach (MSFC) with IASTI, and a Senior Practitioner with EMCC, whose work bridges professional coaching mastery with regenerative leadership. He created the Applied Regenerative Leadership (ARL) ecosystem and its proprietary frameworks: Applied Coaching (AC), Applied Heartstorm (AHS), and Applied Solution Focused (ASF).", "links": [{"l": "Facebook", "h": "https://www.facebook.com/coachalextan"}, {"l": "Instagram", "h": "https://www.instagram.com/coachalextan"}, {"l": "LinkedIn", "h": "https://www.linkedin.com/in/coachalextan"}]}, {"id": "jasna-knez", "name": "Jasna Knez", "title": "CEO at Kreativlab · Executive & Team Coach · Supervisor · Trainer", "img": "img/jurors/jasna-knez.jpg", "bio": "Jasna Knez is an internationally recognized coach, mentor, and supervisor, holding the profession’s highest credentials: ICF Master Certified Coach (MCC), EMCC EIA Master Practitioner, ITCA Team Coach, and EMCC ESIA Coaching Supervisor. She brings extensive experience across diverse cultures, industries, and organizational contexts, with expertise in leadership, team development, culture transformation, and coaching skills. Her systemic and integral perspective, combined with a pragmatic and people-centered approach, enables clients to achieve tangible results, lasting growth, reduced stress, and greater fulfillment in both work and life.", "links": [{"l": "LinkedIn", "h": "https://www.linkedin.com/in/jasna-knez/"}]}, {"id": "elif-elif-suner", "name": "Elif Suner", "title": "Leadership Development Consultant at Enrichia · Coach Supervisor", "img": "img/jurors/elif-elif-suner.jpg", "bio": "Walking alongside leaders, teams, and coaches! For me, leadership has never been about standing alone. It is about cultivating presence, clarity, and trust and having the courage to walk alongside others. This philosophy has shaped my 25+ year journey as a leadership development consultant, executive and team coach, and supervisor of coaches.", "links": [{"l": "LinkedIn", "h": "https://www.linkedin.com/in/elif-suner-mba-med-mcc-8652a318/"}]}, {"id": "deborah-george-feres", "name": "Deborah George-Feres,Ph.D", "title": "MCC · Executive & Leadership Coach, Founder at Indigo Coaching Systems", "img": "img/jurors/deborah-george-feres.jpg", "bio": "Dr. Deborah George-Feres is an ICF Master Certified Coach (MCC) and Board-Certified Coach (BCC) with over 20 years of experience helping leaders establish functional systems and dismantle self-imposed limitations, enabling them to lead with clarity, conviction, and purpose. Her work centers on equipping executives and mission-driven leaders to recalibrate thinking, elevate performance, and catalyze lasting impact for themselves, their teams, and their organizations.", "links": [{"l": "LinkedIn", "h": "https://www.linkedin.com/in/dgfcoach/"}]}, {"id": "cristina-madeira", "name": "Cristina Madeira", "title": "Executive & Team Coach · Senior Mentor · Leadership Faculty · Books Writer", "img": "img/jurors/cristina-madeira.jpg", "bio": "Cristina Madeira is a Human Skills Strategist, Executive & Team Coach, and Leadership Faculty with more than 28 years of international experience in human capital development. She began leading a big team with 24 years old and has since broken barrier, becoming the first Hotel Coach to bring coaching into hospitality and one of the first independent coaches to work directly with major corporations. She has an extensive cross-cultural expertise gained across UK, Germany, Canada, USA, France, Spain, South America, Nordic countries, Asia and the Middle East. Guided by a pioneer spirit and two principles: “Everything is impossible until it’s imagined and done” and “Worse than not having ideas is not even knowing that they exist, Cristina has consistently challenged outdated leadership norms. She believes leadership is not only about results but about evolving humanity,…", "links": [{"l": "LinkedIn", "h": "https://www.linkedin.com/in/cristinamadeira/"}]}, {"id": "tihana-dragicevic", "name": "Tihana Dragicevic", "title": "EMCC MP · ESIA Supervisor · Published author · EQA School of Coaches Founder", "img": "img/jurors/tihana-dragicevic.jpg", "bio": "Tihana Dragicevic is an internationally recognized coach, supervisor, educator, and author with over 15 years of experience in developing coaching excellence across Europe. Her work bridges corporate leadership, deep personal transformation, and systemic change always with a commitment to integrity, curiosity, and human potential. Credentials & Experience • EMCC EIA Master Practitioner & EMCC ESIA Supervisor • ICF Professional Certified Coach (PCC) • Team coach • 4500+ hours of coaching practice • 2500+ hours of supervision • 15 years of international coaching experience as a coach and educator of coaches • Corporate background as trainer and coach in multinational companies", "links": [{"l": "Facebook", "h": "https://www.facebook.com/share/1H3NtZ4CJ4/"}, {"l": "YouTube", "h": "https://www.youtube.com/playlist"}, {"l": "LinkedIn", "h": "https://www.linkedin.com/in/tihanadragicevic/"}]}, {"id": "pilar-pardo-cembrano", "name": "PILAR PARDO CEMBRANO", "title": "Empresas Con Alma Founder · Co-Active Coaching", "img": "img/jurors/pilar-pardo-cembrano.jpg", "bio": "Pilar is an MCC Executive & Team Coach and international trainer who brings soul into leadership, communication, and innovation. As the founder and Alma Mater of Empresas con Alma (Companies with Soul), she helps organizations grow by placing people at the center of success. With over 4,000 hours of coaching experience and a career that began at Procter & Gamble, Pilar has guided leaders and teams worldwide from Airbus to Nestlé, Bayer, Telefónica, and many more through cultural change, leadership development, and new ways of working.", "links": [{"l": "LinkedIn", "h": "https://www.linkedin.com/in/pilarpardocembranocoach/"}]}, {"id": "elzbieta-jablonska", "name": "Elzbieta Jablonska", "title": "Founder and CEO at ARDITO Consulting · Leadership Coach", "img": "img/jurors/elzbieta-jablonska.jpg", "bio": "Elżbieta is a master certified coach MCC and internationally respected expert in leadership, resilience, and longevity, with nearly three decades of global experience. She has guided diplomats, ambassadors, politicians, C-suite executives, military officers, journalists, and nonprofit leaders across 87 countries, helping them sustain clarity, balance, purpose, and long-term well-being in high-pressure roles.", "links": [{"l": "LinkedIn", "h": "https://bit.ly/47bS87V"}]}, {"id": "angela-maria-covas", "name": "Angela María Covas", "title": "Founder & Director of Greatitute Coaching Schoool · Trainer · Author", "img": "img/jurors/angela-maria-covas.jpg", "bio": "Ángela Covas is an MCC Coach accredited by the International Coaching Federation (ICF), writer, trainer, and a global reference in the field of professional coaching. With over two decades of experience, she has dedicated her career to helping people and organizations unleash their full potential through the power of coaching. She is the Founder and Director of Greatitute Coaching School, an ICF-accredited Level 1 and Level 2 program, recognized internationally for its academic excellence, competitive pricing, and above all, its spirit of generosity and community. Greatitute has become one of the most respected schools in the world, where around 30% of students already certified elsewhere decide to repeat their training, and 25% join thanks to personal recommendations.", "links": [{"l": "Facebook", "h": "https://www.facebook.com/angelacovasriera"}, {"l": "Instagram", "h": "https://www.instagram.com/angelacovas/"}, {"l": "LinkedIn", "h": "https://www.linkedin.com/in/angelacovascoachmcc"}]}, {"id": "natalja-petr-galiuk-kausiene", "name": "Natalja Petr Galiuk – Kausiene", "title": "MCC ICF Business Coach · Psychologist · MBA", "img": "img/jurors/natalja-petr-galiuk-kausiene.jpg", "bio": "MCC ICF Business Coach | Psychologist | MBA Expert in team coaching, leadership development and management effectiveness 🎓 Education and certification: Belarusian State University, biologist Vilnius University, International Business School (MBA) Erickson University of Coaching Gold Coach Certificate Elena Chelokidi Team Development Center “Team Coaching: Basics and Patterns” ICF MCC International Coaching Federation, Master Certified Coach Currently completing my certification as a team coach. Official assessor for the International Coaching Organization.", "links": [{"l": "LinkedIn", "h": "https://www.linkedin.com/in/kaushenecoach/"}]}, {"id": "marcell-szabo", "name": "Marcell Szabo", "title": "Executive and Team Coach, The Impacter Development Centre Ltd.", "img": "img/jurors/marcell-szabo.jpg", "bio": "About me: professional, yet human Creating values, empowering personal growth and exploring the impact of individuals are my guiding stars as a professional. As a Master Certified Coach (MCC) with over 5,000 coaching hours, recognised by the International Coaching Federation, I remain passionate about supporting leaders on their journey to gain insights about themselves, achieve their goals, and discover their true purpose through meaningful personal learning. With more than 15 years of experience under my belt in working as a business trainer and executive coach across various organisations, I firmly believe that the power of the human factor, blended with creating shared values, is the essential building block of any purpose-driven leadership, both now and in the future. Working with senior leaders and managers in the corporate sector from companies such as…", "links": [{"l": "LinkedIn", "h": "https://www.linkedin.com/in/marcell-szabo-mcc-a40aa319/"}]}, {"id": "alok-sharma", "name": "Alok Sharma", "title": "Coaching for Life and Leadership · EMCC Senior Practitioner", "img": "img/jurors/alok-sharma.jpg", "bio": "Alok comes from IT industry. Having witnessed the industry grow since 1981, Alok steadily rose to lead in global roles in his 35 years of corporate engagement while enabling several multinational organizations for growth. He has worked closely with business leaders for efficiency and effectiveness in business processes. Alok comes with proven mentoring experience of over two decades, having mentored and coached for performance and growth in his corporate roles. Alok has been formally coaching leaders and emerging leaders in global IT, finance and manufacturing organizations since 2017. He primarily helps leaders to be more effective in their role and make their presence felt in executive rooms by helping them develop abilities to manage priorities, collective success mindset, standing for what is right and think like a CEO. Strong values and ethics remain at the core…", "links": [{"l": "LinkedIn", "h": "https://www.linkedin.com/in/sharmalok"}]}, {"id": "iryna-zolotarevych", "name": "Iryna Zolotarevych", "title": "President at International Upscaling Coaching group · AgileBrain Master Practitioner", "img": "img/jurors/iryna-zolotarevych.jpg", "bio": "Iryna Zolotarevych, MCC ICF, is an executive coach, anti-crisis adviser, and founder of the International School of Upscaling Coaching. With over 25...", "links": [{"l": "Facebook", "h": "https://www.facebook.com/share/1678eurQjv/"}, {"l": "Instagram", "h": "https://www.instagram.com/iryna_zolotarevych"}, {"l": "LinkedIn", "h": "https://www.linkedin.com/in/zolotarevych"}]}, {"id": "dr-navana-kundu", "name": "Dr. Navana Kundu", "title": "Founder at Manarah Edtech · Bestselling Author · Tedx Speaker · Therapist", "img": "img/jurors/dr-navana-kundu.jpg", "bio": "Dr. Navana Kundu, Msc.D is an international bestselling award-winning author, therapist, coach, and Tedx speaker who has dedicated her life to empowering individuals to unlock their full potential. With a doctorate in Metaphysical Science and a specialization in “the effects of meditation on human happiness”, she has become a leading authority on emotional mastery.", "links": [{"l": "Instagram", "h": "https://www.instagram.com/drnavanakundu/"}, {"l": "LinkedIn", "h": "https://www.linkedin.com/in/navana"}]}, {"id": "jayshree-mangesh-kirtane", "name": "Jayshree Mangesh Kirtane", "title": "Master Coach at JK Coaching · Executive Director at Alchemy Mgmt Consultancy", "img": "img/jurors/jayshree-mangesh-kirtane.jpg", "bio": "Jayshree is a Mathematical Economist turned Applied Psychologist and Master Coach. She was a professor of Quantitative Economics for the first 10 years of her career. She serendipitously found herself in a coaching meeting and this meeting gave her the courage to choose a career that involved a 180 degree pivot. Jayshree changed her career path 20 years ago, to become a human process facilitator. She also acquired multiple profiling and assessment certifications of global repute. Jayshree stands as an expert in marrying experiential data with the insights from psychometric instruments and create a learning path for the participants.", "links": [{"l": "Instagram", "h": "https://www.instagram.com/jayshreekirtane"}, {"l": "LinkedIn", "h": "https://www.linkedin.com/in/jayshree-kirtane-06027a9/"}]}, {"id": "julia-louise-rogers", "name": "Julia Louise Rogers", "title": "CEO and Founder at The Dynamics of Everyday Life", "img": "img/jurors/julia-louise-rogers.jpg", "bio": "Julia is an ICF Master Certified Coach (MCC) and an EMCC-accredited Senior Practitioner and Coaching Supervisor with over a decade of formal coaching experience. With advanced training in psychodynamic theory, Julia brings a unique depth to her work with both leaders and fellow coaches, helping them explore the unconscious drivers of behaviour, enhance relational awareness, and develop more effective leadership and coaching styles. Her areas of expertise include:", "links": [{"l": "LinkedIn", "h": "https://www.linkedin.com/in/julia-rogers-cpc-mcc-ma-a2238bb8/"}]}, {"id": "lucia-labouchere", "name": "Lucia Labouchere", "title": "Director at Moodie and Labouchere and The Learn to Lead Project", "img": "img/jurors/lucia-labouchere.jpg", "bio": "Lucia is an organisational psychologist and leadership coach with over two decades of professional experience, working internationally with organisations to design and deliver impactful leadership development programmes. She facilitates one-to-one and team coaching, and serves as a mentor coach and coach trainer. Lucia’s own training course is accredited by the International Coaching Federation (ICF).", "links": [{"l": "LinkedIn", "h": "https://www.linkedin.com/in/lucia-labouchere-1824b936/"}]}, {"id": "julius-c-ordonez", "name": "Julius C. Ordonez, MCC, ACTC", "title": "President & Owner, Benchmark Consulting Executive Coach · Mentor Coach", "img": "img/jurors/julius-c-ordonez.jpg", "bio": "Julius Ordoñez is the President and owner of Benchmark Consulting. He has more than 20 years of solid experience in the areas of organizational, leadership and team development, executive coaching, management consulting, business management, mentoring and writing.", "links": [{"l": "Facebook", "h": "https://facebook.com/julius.ordonez.543"}, {"l": "LinkedIn", "h": "https://www.linkedin.com/in/julius-ordonez/"}]}, {"id": "dr-teresa-rafaela-sacco", "name": "Dr. Teresa Rafaela Sacco", "title": "Public Accountant · Psychoeducator-PNL Trainer-Negotiation", "img": "img/jurors/dr-teresa-rafaela-sacco.jpg", "bio": "Coach Internacional / Conferencista / Autora Contadora Pública graduada en la Universidad de Buenos Aires, con un Postgrado Internacional en Dirección Estratégica y formación en Negociación en Harvard. Reconocida como Master Coach Profesional (MCC) por la International Coach Federation (ICF-USA), cuenta con una sólida formación en Coaching Organizacional, Político, Ontológico, por Competencias y por Valores, además de capacitación en Coaching Sistémico junto a Alain Cardon.", "links": [{"l": "Facebook", "h": "https://www.facebook.com/teresa.sacco.773"}, {"l": "Instagram", "h": "https://www.instagram.com/teresacco_/"}, {"l": "LinkedIn", "h": "https://www.linkedin.com/in/teresa-sacco-mcc-2bba0623/"}]}, {"id": "wendy-preyssler", "name": "Wendy Preyssler", "title": "Founder at Coaching By Wendy · Executive & Leadership Coach", "img": "img/jurors/wendy-preyssler.jpg", "bio": "Empowered by an authentic passion for guiding professionals to unlock their true leadership potential and lead fulfilling lives, Wendy Preyssler, MCC, has dedicated her career to supporting the success of her clients. As an International Coaching Federation (ICF) Master Certified Coach, Wendy has garnered numerous global awards, including being named the Corporate Vision Executive & Leadership Coach of the Year (2025) and Corporate LiveWire Business Leadership Coach of the Year (2025, 2024, 2023) Hall of Fame.", "links": [{"l": "Facebook", "h": "https://www.facebook.com/coachingbywendy"}, {"l": "Instagram", "h": "https://www.instagram.com/coachingbywendy/"}, {"l": "LinkedIn", "h": "https://www.linkedin.com/in/wendy-preyssler-mcc/"}]}, {"id": "ramasubban-sankaran-ramanathan", "name": "Ramasubban Sankaran Ramanathan", "title": "Founder Emeritus at Coacharya", "img": "img/jurors/ramasubban-sankaran-ramanathan.jpg", "bio": "As a Founder Emeritus and Mentor Coach, Ram brings an accomplished 45-year to Coacharya. He oversees coaching and training content and approach, and is responsible for creating all proprietary coaching models for Coacharya. Ram held C-suite leadership positions for 25-years during which he turned around companies, helped a billion dollar conglomerate, supervised multinational joint ventures, advised the governments of Indonesia and Singapore, angel invested/incubated technology start-ups, and consulted family businesses, small-to-medium enterprises and nonprofit institutions, He stresses the principles of lean management, customer orientation and quality assurance in all facets of business.", "links": [{"l": "LinkedIn", "h": "https://www.linkedin.com/in/ramsramanathan/"}]}, {"id": "roberta-pagliarulo", "name": "Roberta Pagliarulo", "title": "Executive & Leadership Coach · ICF Mentor and Trainer · Speaker", "img": "img/jurors/roberta-pagliarulo.jpg", "bio": "Roberta Pagliarulo is a Master Certified Coach (MCC) with over 15 years of international experience in executive coaching, leadership development, and mentor coaching. She has worked with senior leaders and founders across Europe and the Middle East, helping them navigate complex transitions and strengthen their leadership impact. Roberta has delivered thousands of hours of coaching and training, and has played a key role in the development of the coaching profession by designing and delivering four ICF-accredited CCE programs. She has also mentored and assessed hundreds of coaches within ICF-accredited schools.", "links": [{"l": "LinkedIn", "h": "https://www.linkedin.com/in/roberta-pagliarulo-2240a618/"}]}, {"id": "maureen-ann-miller", "name": "Maureen Ann Miller", "title": "President at Rewired2Change Executive Coaching Inc.", "img": "img/jurors/maureen-ann-miller.jpg", "bio": "I believe we create our reality the moment we acknowledge and act on what matters most. I do this through coaching and training people on the use of my proprietary TRU^ID program. I bring 25+ years of business experience and 6000+ hours of Coaching experience to coaching leaders and professionals in the not-for-profit, for-profit and government sectors. I am an Executive Coach and received my coaching training through CoachU. I hold a Bachelor of Education through the University of Calgary.", "links": [{"l": "LinkedIn", "h": "https://www.linkedin.com/in/maureen-miller-84ab35/"}]}, {"id": "maria-iris-hoeppe", "name": "Maria-Iris Höeppe", "title": "Leadership Performance Coach at ALMADIDO · Author", "img": "img/jurors/maria-iris-hoeppe.jpg", "bio": "Maria-Iris Höeppe is a Master Certified Coach-MCC-ICF and the author of “The Book about Changes”. She is also certified as an executive coach and team coach from “Coaching and Leadership International-Canada”.", "links": [{"l": "Facebook", "h": "https://www.facebook.com/mariairishoeppe/"}, {"l": "Instagram", "h": "https://www.instagram.com/maria_iris_hoeppe_mcc/"}, {"l": "LinkedIn", "h": "https://bit.ly/4ma9DtS"}]}, {"id": "dr-lisa-leit", "name": "Dr. Lisa Leit", "title": "Founder + Director of Training at Happy Whole Human Institute", "img": "img/jurors/dr-lisa-leit.jpg", "bio": "Dr. Lisa Leit is an ICF Master Certified Coach (MCC) and EMCC Senior Practitioner and Certified Supervisor (SP, ESIA) with over 20 years of experience empowering individuals, teams, and organizations to achieve transformative growth. As the founder of Happy Whole Human®, Lisa has created a globally recognized, ICF-accredited coach training ecosystem (Levels 1 to 3 and Team Coach) and provides ICF-aligned mentor coaching and EMCC supervision to support the next generation of bright stars in the coaching world.", "links": [{"l": "Facebook", "h": "https://www.facebook.com/drlisaleit/"}, {"l": "LinkedIn", "h": "https://www.linkedin.com/in/lisaleit"}, {"l": "X", "h": "https://x.com/happywholehuman"}]}, {"id": "bernard-chanliau", "name": "Bernard Chanliau", "title": "Founder / CEO at BC Team Coaching Ltd · ACTC-ICF Leadership Coach", "img": "img/jurors/bernard-chanliau.jpg", "bio": "Bernard Chanliau, a distinguished Master Certified Coach (MCC) and (ACTC) ICF leadership coach with over two decades of experience (7000+ hours), is recognized for pioneering methodologies that bridge the corporate-startup divide. His systemic approach to leadership transformation has earned international acclaim, including recognition for outstanding contributions to the coaching profession.", "links": [{"l": "Instagram", "h": "https://www.instagram.com/leadershipteamcoaching"}, {"l": "LinkedIn", "h": "https://www.linkedin.com/in/bernardchanliaumcc/"}, {"l": "X", "h": "https://x.com/BCoach_Exec"}]}, {"id": "joanne-blackerby", "name": "Joanne Blackerby", "title": "Founder, ClarityCoachME™ · Co-Founder, Adaptive Coaching™ · Senior EMCC", "img": "img/jurors/joanne-blackerby.jpg", "bio": "Joanne Wong Blackerby, MCC is a Master Certified Coach, coaching supervisor, educator, and framework architect with over two decades of experience helping leaders, coaches, and organizations navigate the complex intersection of identity, power, culture, and ethical practice. She is the Founder of ClarityCoachME™ and Co-Founder of Adaptive Coaching™, and the creator of four original frameworks: The Core Four™ (Competence, Ethics, Values, Culture), The 3 R’s of Reflective Practice™ (Reflective, Reflexive, Responsive), The Rule of Four™, and Culturally Sustainable Coaching Practice™.", "links": [{"l": "LinkedIn", "h": "http://linkedin.com/in/joanne-blackerby"}]}, {"id": "genevieve-abdelfatah-desautels", "name": "GENEVIÈVE ABDELFATAH DESAUTELS", "title": "CRHA · Distinction Fellow · ASC-C.Dir. · MBA", "img": "img/jurors/genevieve-abdelfatah-desautels.jpg", "bio": "Entrepreneur in Workforce Development Founder of Amplio Stratégies, a company specializing in strategic coaching for managers, and Illuxi, a technology platform dedicated to skills development. Multisectoral Expert and Executive Leader With over 30 years of experience, she has supported thousands of leaders and professionals from various industries through training and executive coaching, totaling more than 30,000 individuals trained and 4,500 hours of coaching. She has chaired and served on multiple boards of directors for over 20 years. Her background spans the private, public, parapublic, and nonprofit sectors, giving her a transversal and systemic understanding of the world of work.", "links": [{"l": "Facebook", "h": "https://www.facebook.com/gendesautels"}, {"l": "Instagram", "h": "https://www.instagram.com/gendesautels/"}, {"l": "LinkedIn", "h": "https://www.linkedin.com/in/genevievedesautels/"}]}, {"id": "nada-jreissati", "name": "Nada Jreissati", "title": "MCC · Executive & Leadership Coach · Founder of PragmaDoms", "img": "img/jurors/nada-jreissati.jpg", "bio": "I’ve always focused on real-world results over recognition, but a few milestones stand out: Nominated by CEO Magazine and named a Top LinkedIn Voice, recognizing my leadership in coaching and business growth across the region. Regularly selected as a Subject Matter Expert for the ICF Competency Model Review one of the few global coaches invited to shape the future of our profession. ICF Master Certified Coach (MCC) with over 10,000 leaders coached and 500+ coaches trained. Regular guest speaker and panelist in ICF events (UAE and international), including sessions in Ukraine and other global forums.", "links": [{"l": "Facebook", "h": "https://www.facebook.com/nada.jreissati"}, {"l": "Instagram", "h": "https://www.instagram.com/nada.jreissati/"}, {"l": "LinkedIn", "h": "https://www.linkedin.com/in/nadajreissati/"}]}, {"id": "rekha-hatkanagalekar", "name": "Rekha Hatkanagalekar", "title": "Leadership Coach · Coach Mentor · Coach Supervisor · MCC", "img": "img/jurors/rekha-hatkanagalekar.jpg", "bio": "Bio Write-Up I am an Executive and Leadership coach holding a Master Certified Coach credential from ICF. I come with 35 odd years of rich wholistic experience as a Business Head, HR Head and Academician. I have spent 20 plus years in senior leadership roles including as a partner in a startup software firm. During this time and later as a full time coach, I have coached/mentored and developed 200+ leaders towards business, professional and personal goals. Coaching: Over the last 30 odd years of professional life, I have accumulated 4000+ coaching hours, coaching people on life and professional goals. My clients are from different demography’s and from across the world.", "links": [{"l": "LinkedIn", "h": "https://www.linkedin.com/in/rekhah/"}]}, {"id": "giorgia-franceschini", "name": "Giorgia Franceschini", "title": "Co-Founder & Corporate Coach at T•CoP - The Coaching Pros", "img": "img/jurors/giorgia-franceschini.jpg", "bio": "I combine my initial passion for NLP (Neuro-Linguistic Programming) with a great interest in Coaching, which I have deepened in Italian and international schools, acquiring the MCC credential. Together with Luca Berni and Sarah Fuligni, I’m a founding member of the two entities that comprise T · CoP, namely The Coaching Pros Srl and TheNCS, The Neuroscience Coaching School. Today, as a Coach, I accompany Managers and professionals to rediscover and express their natural Leadership. Since 2018, I have had an active role in the ICF Italy board and in 2021, I was the ICF Italy President", "links": [{"l": "Facebook", "h": "https://www.facebook.com/people/Giorgia-Franceschini/pfbid027TeaJj945VqZRHsiGZwgxfdoCJXYDTNsFEBsHJYoh68NnGWbFXKrP8ae7Ww5s6Tul/"}, {"l": "Instagram", "h": "https://www.instagram.com/giorgia_fran"}, {"l": "LinkedIn", "h": "https://linkedin.com/in/giorgiafranceschini"}]}, {"id": "latha-bhonsle", "name": "Latha Bhonsle", "title": "Founder, Principal Coach & Facilitator at Mindseye", "img": "img/jurors/latha-bhonsle.jpg", "bio": "With 30 plus years of diverse experience in corporate and entrepreneurial leadership roles, Latha brings contextual knowledge of Leadership, business growth, Strategy and Impact across various markets and industries. Apart from deep work in India, Latha has worked globally handling clients and markets in US, Europe, South Asia and Africa and brings the Global context in her coaching and facilitation relationships. She has experience of large-scale execution, Organization Development & Change management, Team building and Leadership Development which involves bringing disparate teams and leaders together to achieve ambitious goals and create impact.", "links": [{"l": "LinkedIn", "h": "https://www.linkedin.com/in/lathabhonsle/"}]}, {"id": "melissa-dawn", "name": "Melissa Dawn", "title": "Founder & CEO, CEO of Your Life · Keynote Speaker · Bestselling Author", "img": "img/jurors/melissa-dawn.jpg", "bio": "Melissa Dawn is a Master Certified Coach (MCC), international keynote speaker, bestselling author, and founder of CEO of Your Life recognized globally as one of the top leadership coaching companies for over six consecutive years. Fewer than 4% of coaches worldwide hold the prestigious MCC designation, a testament to Melissa’s depth, mastery, and unwavering commitment to transformational change.", "links": [{"l": "Facebook", "h": "https://www.facebook.com/joyfulcareer"}, {"l": "X", "h": "https://x.com/CEOofYourLife"}, {"l": "Instagram", "h": "https://www.instagram.com/ceo_of_your_life/"}]}, {"id": "dr-soha-chahine", "name": "Dr. Soha Chahine", "title": "Managing Director at Forward Training and Consulting", "img": "img/jurors/dr-soha-chahine.jpg", "bio": "Dr. Soha Chahine is an Organizational Psychologist, ICF-accredited PCC (Professional Certified Coach), award-winning corporate coach and trainer, TEDx speaker, and founder of Forward Training and Consulting known for shaping human-centered cultures where people lead with presence, perform with purpose, and adapt at the speed of change. Blending behavioral science with business strategy, Soha designs leadership ecosystems that are both scalable and human-centered. She is the author of The Talent Matrix Playbook and a contributor to Harvard Business Review Arabia. Her work bridges theory and practice translating psychological insight into measurable business results.", "links": [{"l": "LinkedIn", "h": "https://www.linkedin.com/in/sohachahine/"}]}, {"id": "pratishtha-bhalla", "name": "Pratishtha Bhalla", "title": "Leadership & Mental Wellness Coach at Coachista Lifestyle Consulting · Author", "img": "img/jurors/pratishtha-bhalla.jpg", "bio": "Bio: Helping Leaders Heal Anxiety, Master Emotional Resilience & Lead with Confidence ICF-PCC accredited Leadership & Mental Wellness Coach | NLP Trainer | Hypnotherapy Practitioner | Access Bars Practitioner | Mindfulness Coach| Author Pratishtha Bhalla empowers high-achieving leaders to overcome anxiety, burnout, and self-doubt, guiding them toward resilience, clarity, and empowered leadership. Her holistic, neuroscience-informed approach blends transformational coaching with mind-body techniques, helping professionals lead with emotional intelligence even in the most demanding environments.", "links": [{"l": "LinkedIn", "h": "https://www.linkedin.com/in/pratishthabhalla/"}]}, {"id": "cheri-s-allen-mcc", "name": "Cheri S. Allen, MCC", "title": "CEO & Founder @CHOICE Coaching & Consulting LLC", "img": "img/jurors/cheri-s-allen-mcc.jpg", "bio": "Chéri S. Allen is a Master Certified Coach with over 3,500 coaching hours and more than 30 years of Federal and private sector experience in more than fifteen agencies in human capital management and development, executive coaching, change management consulting, leadership, and organizational development. Experienced Master Credentialed Coach and Strategist with over 25 years of expertise in leadership coaching, change management, and executive coaching. Proven track record in implementing successful coaching strategies in remote work environments.", "links": [{"l": "LinkedIn", "h": "http://bit.ly/4l0pcTw"}]}, {"id": "cris-bolivar", "name": "Cris Bolivar", "title": "Founder and CEO of Essential Institute · Master Essential Coach", "img": "img/jurors/cris-bolivar.jpg", "bio": "• Master Essential Coach, consultant, trainer, supervisor, mentor-coach and international keynote speaker. • Founder and CEO of Essential Institute. • 30 years accompanying processes of personal, organizational and social evolutionary transformation. • Degree in Organizational Psychology with an Excellent Degree, University of Barcelona.", "links": [{"l": "Facebook", "h": "https://www.facebook.com/crisbolivaressentialinstitute"}, {"l": "Instagram", "h": "https://www.instagram.com/crisbolivarcb/"}, {"l": "LinkedIn", "h": "https://linkedin.com/in/crisbolivar"}]}, {"id": "rae-t-chois-mcc", "name": "Rae T. Chois", "title": "Owner at Choice International · The Confidence Coach for Top Leaders and Coaches", "img": "img/jurors/rae-t-chois-mcc.jpg", "bio": "", "links": []}];
window.KT_CATEGORIES = [{"id": "life", "title": "LIFE", "blurb": "Coaching that helps people shape how they live.", "cats": [{"n": "Interpersonal Relationships Coach", "d": "Recognizing coaches who help individuals develop stronger, healthier, and more fulfilling relationships in their personal and professional lives.", "w": "Relationship coaches, communication experts, and professionals specializing in interpersonal skills."}, {"n": "Parenting coach", "d": "Honoring coaches who guide parents in fostering strong, healthy, and positive relationships with their children.", "w": "Certified parenting coaches, child psychologists incorporating coaching, and professionals specializing in family dynamics."}, {"n": "Personal Development and Growth coach", "d": "Celebrating coaches who empower individuals to unlock their full potential and achieve personal growth.", "w": "Life coaches, personal development experts, or professionals guiding clients toward self-improvement."}, {"n": "Self Confidence coach", "d": "Recognizing coaches who help individuals build self-esteem, overcome self-doubt, and develop unshakable confidence.", "w": "Confidence coaches, mindset coaches, or professionals specializing in self-esteem improvement."}, {"n": "Mindfulness and Meditation coach", "d": "Recognizing coaches who guide clients toward presence, stillness, and sustainable mindfulness practice.", "w": "Mindfulness coaches, meditation teachers working through coaching, and practitioners of contemplative practice."}, {"n": "Manifestation coach", "d": "Recognizing coaches who help individuals manifest their desires by aligning thoughts, emotions, and actions with their goals.", "w": "Manifestation coaches, mindset coaches, or professionals using the law of attraction in their coaching."}, {"n": "Mindset and Empowerment coach", "d": "Recognizing coaches who help clients shift limiting beliefs and build an empowered inner stance.", "w": "Mindset coaches, empowerment practitioners, and coaches specializing in belief and identity work."}, {"n": "NLP coach", "d": "Recognizing coaches who use Neuro-Linguistic Programming techniques to help clients reprogram thoughts and behaviors for success.", "w": "Certified NLP coaches, mindset coaches incorporating NLP, or professionals specializing in behavior change."}, {"n": "Reiki Healer Coach", "d": "Celebrating professionals who integrate Reiki healing into coaching to promote energy balance and holistic well-being.", "w": "Certified Reiki healers, energy coaches, or wellness practitioners incorporating Reiki into coaching."}, {"n": "Spiritual Coach", "d": "Honoring coaches who guide individuals in connecting with their higher selves, finding purpose, and deepening spiritual awareness.", "w": "Spiritual coaches, life coaches with a spiritual focus, or professionals incorporating energy and consciousness work into coaching."}, {"n": "Personal Breakthrough coach", "d": "Recognizing professionals who help clients experience major breakthroughs in life, business, or personal development.", "w": "Breakthrough coaches, mindset transformation coaches, or professionals guiding clients through life-changing moments."}, {"n": "Work-life balance coach", "d": "Recognizing coaches who help individuals restore rhythm between work, rest, relationships, and personal life.", "w": "Work-life balance coaches and practitioners supporting sustainable living and energy management."}, {"n": "Energy Healer coach", "d": "Recognizing coaches who integrate energy-healing practice with coaching conversations and client transformation.", "w": "Energy healers working through coaching, and practitioners combining energetic and conversational work."}, {"n": "Life Purpose Coach", "d": "Recognizing coaches who help clients clarify vocation, meaning, and the direction of a life they can stand behind.", "w": "Purpose coaches, life coaches, and practitioners guiding clients through meaning and direction work."}]}, {"id": "health", "title": "HEALTH & WELL-BEING", "blurb": "Coaching that supports healthier habits and everyday well-being.", "cats": [{"n": "Holistic coach", "d": "Recognizing coaches who take a mind-body-spirit approach to helping individuals achieve balance, healing, and personal growth.", "w": "Holistic wellness coaches, life coaches integrating multiple healing modalities, and professionals using a whole-person coaching approach."}, {"n": "Fitness coach", "d": "Honoring coaches who help individuals build strength, improve endurance, and maintain an active lifestyle through personalized fitness programs.", "w": "Personal trainers, fitness coaches, and health professionals specializing in physical well-being."}, {"n": "Nutrition coach", "d": "Recognizing coaches who help clients build sustainable relationships with food, nourishment, and daily health habits.", "w": "Nutrition coaches and practitioners guiding clients through food, habit, and lifestyle change."}, {"n": "Weight loss coach", "d": "Recognizing coaches who support clients through lasting weight-change journeys with dignity, structure, and care.", "w": "Weight-loss coaches and health practitioners specializing in sustainable body-composition change."}, {"n": "Stress and Anxiety Coach", "d": "Honoring professionals who help clients manage and reduce stress and anxiety through coaching techniques.", "w": "Certified stress management coaches, mindfulness experts, and therapists who incorporate coaching into their practice."}, {"n": "Health Coach", "d": "Recognizing coaches who take a comprehensive approach to guiding clients toward improved overall health and well-being.", "w": "Health coaches specializing in preventive care, chronic disease management, or holistic health improvement."}, {"n": "Intimacy and Relationship Coach", "d": "Honoring coaches who help individuals or couples deepen intimacy, strengthen relationships, and enhance emotional connection.", "w": "Certified relationship coaches, intimacy coaches, or professionals working with couples or individuals to improve love and connection."}, {"n": "Childhood Trauma Coach", "d": "Recognizing coaches who help clients heal from childhood wounds and break free from limiting patterns.", "w": "Trauma-informed coaches, therapists integrating coaching, or professionals specializing in inner child healing."}, {"n": "Hypnosis Coach", "d": "Honoring coaches who use hypnosis to help clients achieve breakthroughs in habits, behavior, and mindset.", "w": "Certified hypnotherapists, mindset coaches, or professionals integrating hypnosis into coaching."}, {"n": "Recovery and Addiction coach", "d": "Celebrating professionals who support individuals in overcoming addiction and maintaining long-term recovery.", "w": "Certified recovery coaches, addiction specialists, or professionals integrating coaching into rehabilitation programs."}, {"n": "Fertility coach", "d": "Recognizing coaches who guide individuals or couples through fertility challenges with emotional, physical, and lifestyle support.", "w": "Fertility coaches, reproductive health specialists, or professionals integrating coaching into fertility treatment."}, {"n": "ADHD coach", "d": "Recognizing coaches who support clients with ADHD in attention, structure, self-trust, and daily functioning.", "w": "ADHD coaches and practitioners specializing in neurodivergent-aware coaching."}, {"n": "Dis-ease Transformational Coach", "d": "Recognizing coaches who walk with clients through illness, diagnosis, and the inner work of living with disease.", "w": "Coaches specializing in illness, recovery, and transformational health journeys."}, {"n": "Wellness Coach", "d": "Celebrating professionals who help individuals achieve holistic well-being through lifestyle changes and personalized coaching.", "w": "Wellness coaches specializing in fitness, nutrition, mental health, and emotional well-being."}]}, {"id": "business", "title": "BUSINESS & EXECUTIVE", "blurb": "Coaching that develops leadership and professional growth.", "cats": [{"n": "Leadership Coach", "d": "Recognizing coaches who empower individuals to become effective leaders by improving decision-making, influence, and leadership presence.", "w": "Leadership coaches specializing in executive, corporate, or personal leadership development, with a proven track record of helping leaders transform their skills."}, {"n": "Sales, Marketing, and Branding Coach", "d": "Honoring coaches who help individuals and businesses refine sales strategies, enhance marketing efforts, and build compelling brands.", "w": "Coaches specializing in sales techniques, marketing strategies, or brand positioning."}, {"n": "Communication and Public Speaking Coach", "d": "Celebrating coaches who transform individuals into confident, persuasive, and impactful speakers in public, corporate, or personal settings.", "w": "Coaches specializing in public speaking, storytelling, media training, or corporate communication."}, {"n": "Finance and Investment Coach", "d": "Recognizing coaches who help clients master financial literacy, wealth management, and smart investing strategies.", "w": "Coaches specializing in personal finance, wealth building, or investment strategies."}, {"n": "Digital Marketing Coach", "d": "Recognizing coaches who help clients build digital presence, campaigns, and modern marketing capability.", "w": "Digital marketing coaches and practitioners guiding clients through online growth and visibility."}, {"n": "Conflict Resolution Coach", "d": "Recognizing coaches who help individuals and teams navigate conflicts, strengthen relationships, and create harmonious workplaces.", "w": "Coaches specializing in mediation, corporate conflict resolution, or personal dispute coaching."}, {"n": "HR Coach", "d": "Celebrating coaches who help organizations and individuals elevate workplace culture, improve HR practices, strengthen talent development, and build high-performing teams.", "w": "HR consultants, talent development coaches, organizational culture specialists, or professionals who coach leaders, teams, or HR departments."}, {"n": "Real Estate Coach", "d": "Recognizing coaches who guide individuals, agents, and investors in mastering real estate strategies and building long-term property growth.", "w": "Real estate investment coaches, property business mentors, real estate sales coaches, or professionals supporting buying, selling, investing, or scaling."}, {"n": "Work-Life Balance Entrepreneurs Coach", "d": "Recognizing coaches who help entrepreneurs hold both ambition and a life that remains livable.", "w": "Coaches working with founders and entrepreneurs on energy, boundaries, and sustainable growth."}, {"n": "Copywriter and Writing Coach", "d": "Recognizing coaches who help clients find voice, craft, and writing that moves people to act.", "w": "Writing coaches, copy coaches, and practitioners developing client voice and written communication."}, {"n": "Performance and Productivity Coach", "d": "Recognizing coaches who optimize focus, time management, and peak performance in individuals and teams.", "w": "Coaches specializing in productivity, efficiency, and performance improvement."}, {"n": "Job / Career Transition Coach", "d": "Honoring professionals who help individuals successfully navigate career changes and job transitions.", "w": "Coaches specializing in career transitions, job searching, or career growth."}, {"n": "Business Growth and Strategy Coach", "d": "Recognizing coaches who help owners and leaders grow businesses with clearer strategy and stronger execution.", "w": "Business growth coaches, strategy coaches, and practitioners working with scaling organizations."}, {"n": "Business Executive Coach", "d": "Recognizing coaches who mentor executives to enhance leadership, decision-making, and organizational impact.", "w": "Coaches specializing in executive coaching and corporate leadership, including work with senior leaders and CEOs."}]}, {"id": "teams", "title": "TEAMS & ORGANISATIONS", "blurb": "Coaching that helps people work and grow together.", "cats": [{"n": "Best Organizational Coaching Program", "d": "Recognizing outstanding coaching programs that have significantly enhanced an organization’s culture, leadership, and workforce performance.", "w": "Internal or outsourced coaches who have implemented a structured coaching program within an organization. Organizations themselves can also submit successful programs."}, {"n": "Executive Coaching Firm of the Year", "d": "Honoring coaching firms that specialize in transforming executives into high-performing leaders through strategic coaching initiatives.", "w": "Executive coaching firms or independent coaches working internally or externally with organizations to coach senior leaders and C-suite executives."}, {"n": "Leadership Coaching Firm of the Year", "d": "Celebrating coaching firms that have successfully enhanced leadership skills across different organizational levels.", "w": "Leadership coaching firms, internal leadership development teams, or outsourced coaches working directly with organizations."}, {"n": "Best Team Coaching Initiative", "d": "Recognizing coaching programs that have helped teams enhance collaboration, communication, and productivity.", "w": "Internal coaches within organizations, external team coaches, or organizations that have implemented structured team coaching initiatives."}, {"n": "Best Remote Team Coaching Program", "d": "Honoring coaching initiatives that successfully support and develop remote or hybrid teams.", "w": "Organizations, internal remote team coaches, or external coaches who have implemented remote coaching programs."}, {"n": "Diversity and Inclusion Coaching Excellence", "d": "Recognizing coaching work that strengthens belonging, equity, and inclusive culture inside organizations.", "w": "Coaches, firms, or internal programs focused on diversity, inclusion, and belonging through coaching."}, {"n": "Best Coaching for Employee Well-Being", "d": "Honoring coaching initiatives that prioritize employee mental health, resilience, and overall well-being.", "w": "Internal HR or well-being teams offering coaching, external coaches specializing in employee wellness, or organizations with well-being coaching programs."}, {"n": "Innovative Coaching Program of the Year", "d": "Recognizing coaching programs that introduce a new method, design, or application with clear organizational impact.", "w": "Internal or external coaches and organizations presenting an innovative coaching program."}, {"n": "Sustainable Growth Through Coaching", "d": "Recognizing coaching that helps organizations grow in ways that last commercially, culturally, and humanly.", "w": "Coaches, firms, or internal programs demonstrating sustainable organizational growth through coaching."}, {"n": "Global Impact Coaching Program", "d": "Recognizing coaching programs whose work crosses borders and creates impact across cultures or regions.", "w": "Coaches, firms, or organizations running coaching programs with international or cross-cultural reach."}, {"n": "Mentor of the Year (Organization)", "d": "Recognizing an outstanding mentor who has positively influenced individuals within an organization through structured coaching and mentorship.", "w": "Internal mentors within organizations or external coaches who act as dedicated mentors to employees or leaders."}, {"n": "High-Performance Coaching Award", "d": "Honoring coaching programs that drive high performance among employees, leaders, or teams.", "w": "Internal performance coaches, external coaching firms, or organizations implementing high-performance coaching."}, {"n": "Client-Centric Coaching Excellence", "d": "Recognizing coaching work that places the client’s lived outcome at the center of design, practice, and measurement.", "w": "Coaches, firms, or programs demonstrating distinctive client-centric coaching practice."}, {"n": "Corporate Coaching Program of the Year", "d": "Recognizing a corporate coaching program that has changed how an organization leads, develops, and performs.", "w": "Internal coaches, partner firms, or organizations submitting a corporate coaching program."}]}];
